window.taxV603LoadEntry=function(){if(!['income','expense'].includes(activeTab))return;const row=data603().ledger.find(e=>e.id===editingTaxEntryIdV603&&e.kind===activeTab);if(!row)return;for(const [id,key] of [['tax603EntryDate','date'],['tax603EntrySource','source'],['tax603EntryAmount','amount'],['tax603EntryClass','taxClass'],['tax603EntryNote','note'],['tax603EntryNet','net'],['tax603EntryCredit','credit']]){const e=document.getElementById(id);if(e)e.value=row[key]??''}const b=document.getElementById('tax603SaveEntryBtn');if(b)b.textContent='Simpan Perubahan';};
