async function file603(el){const f=el?.files?.[0];if(!f)return null;if(f.size>120*1024)throw Error('Bukti maksimal 120 KB agar penyimpanan lokal aman.');if(!['image/png','image/jpeg','application/pdf'].includes(f.type))throw Error('Bukti harus PDF/JPG/PNG.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});return {name:f.name.slice(0,90),mime:f.type,data:content};}
window.taxV603SaveEntry=async function(kind){if(!allowSettings())return toast('Tidak ada izin mengubah data pajak.','error');const date=val603('tax603EntryDate'),amount=num603('tax603EntryAmount'),taxClass=val603('tax603EntryClass'),source=val603('tax603EntrySource'),note=val603('tax603EntryNote'),netRaw=val603('tax603EntryNet'),credit=num603('tax603EntryCredit');if(!taxV597ValidDate(date)||!date||!date.startsWith(String(activeYear)))return toast('Tanggal harus berada dalam tahun pajak yang dipilih.','error');if(!validMoney603(amount)||amount===0||!validMoney603(credit)||netRaw!==''&&!validMoney603(taxV604ParseMoney(netRaw)))return toast('Periksa nominal, neto, dan kredit pajak.','error');if(kind==='expense'&&source==='personal'&&taxClass==='deductible')return toast('Biaya pribadi tidak boleh dikategorikan biaya fiskal.','error');if(kind==='income'&&source!=='business'&&taxClass==='umkm')return toast('PPh Final UMKM pada modul ini hanya untuk omzet usaha; klasifikasikan penghasilan lain sesuai jenisnya.','error');let attachment=null;try{attachment=await file603(document.getElementById('tax603EntryFile'))}catch(e){return toast(e.message,'error')}const old=data603().ledger.find(e=>e.id===editingTaxEntryIdV603);const id=old?.id||'tx603-'+Date.now()+'-'+Math.random().toString(36).slice(2);mutate603((old?'Perubahan':'Catatan')+' '+(kind==='income'?'penghasilan':'pengeluaran')+' tersimpan.',c=>{const entry={id,kind,date,source,amount,taxClass,note,net:netRaw===''?null:taxV604ParseMoney(netRaw),credit,file:attachment||old?.file||null};c.ledger=old?c.ledger.map(e=>e.id===id?entry:e):[entry,...c.ledger];editingTaxEntryIdV603=''})};
function progressive603(taxable){let left=Math.max(0,Math.floor(taxable/1000)*1000),tax=0;const tranches=[[60000000,.05],[190000000,.15],[250000000,.25],[4500000000,.30],[Infinity,.35]];const items=[];for(const [width,rate] of tranches){if(left<=0)break;const base=Math.min(left,width);const val=Math.round(base*rate);tax+=val;items.push({base,rate,tax:val});left-=base;}return{tax,items}}
function calculation603(a){const c=data603(),p=c.profileV603,rows=listTaxLedger603('income'),costs=listTaxLedger603('expense');const nonfinal=rows.filter(e=>e.taxClass==='normal'),umkm=rows.filter(e=>e.taxClass==='umkm');const salary=nonfinal.filter(e=>e.source==='salary'),business=nonfinal.filter(e=>e.source==='business'||e.source==='freelance');const other=nonfinal.filter(e=>e.source!=='business'&&e.source!=='freelance'&&e.source!=='salary');const salaryNet=salary.reduce((t,e)=>t+(e.net===null?e.amount:e.net),0);const otherNet=other.reduce((t,e)=>t+(e.net===null?e.amount:e.net),0);const posNormalGross=c.regime==='normal'?a.rows.reduce((t,r)=>t+r.auto,0):0;const posHpp=c.regime==='normal'?(Array.isArray(db?.sales)?db.sales:[]).filter(s=>saleDate(s).startsWith(String(activeYear))&&!s.returned).reduce((t,s)=>{const gross=Math.max(0,Number(s.total)||0),returned=Math.min(gross,Math.max(0,Number(s.returnedAmount)||0)),ratio=gross?(gross-returned)/gross:0;return t+Math.max(0,Number(s.cost)||0)*ratio},0):0;const businessGross=business.reduce((t,e)=>t+e.amount,0)+posNormalGross;const deductions=costs.filter(e=>e.taxClass==='deductible'&&e.source!=='personal').reduce((t,e)=>t+e.amount,0);const credits=rows.reduce((t,e)=>t+Math.max(0,Number(e.credit)||0),0);const method=String(p.method||'bookkeeping');let bn=0,warning='';let nppnReady=false;if(method==='nppn'){
 const annualGross=businessGross+a.total;const rate=Number(p.nppnRate);nppnReady=c.type==='op'&&annualGross<4800000000&&p.nppnNotified===true&&rate>0&&rate<=100;
 if(nppnReady)bn=Math.round(businessGross*rate/100);else warning='NPPN belum dapat dihitung: cek pemberitahuan DJP, omzet agregat < Rp4,8 miliar, dan persentase norma resmi sesuai KLU/wilayah.';
 }else bn=Math.max(0,businessGross-deductions-posHpp);
 const net=salaryNet+otherNet+bn,ptkp=ptkp603(p),pkp=Math.max(0,net-ptkp),pr=progressive603(pkp);const due=method==='nppn'&&!nppnReady?null:(c.type==='op'?pr.tax:null);const p25paid=c.paymentRecordsV603.filter(e=>e.kind==='pph25'&&e.year===activeYear&&e.ntpn&&e.paidDate).reduce((t,e)=>t+Number(e.amount||0),0);const creditsTotal=credits+p25paid;const balance=due===null?null:due-creditsTotal;return {due,net,ptkp,pkp,pr,salaryNet,otherNet,businessGross,deductions,posHpp,posNormalGross,bn,credits:creditsTotal,balance,warning,nppnReady,method,umkmGross:umkm.reduce((t,e)=>t+e.amount,0),finalTax:a.tax};}
function renderCalculateV603(a){const c=data603(),p=c.profileV603,d=calculation603(a),isOP=c.type==='op';return `<div class="taxv-filter">${yearSelector()}<span class="taxv-status">${activeYear<2026?'Acuan: PP 55/2022':'Acuan: PP 20/2026 + peralihan'}</span></div>${metrics([['PPh Final UMKM • estimasi',a.tax===null?'Belum layak / belum aktif':money(a.tax)],['PPh OP progresif • estimasi',d.due===null?'Belum tersedia':money(d.due)],['PTKP',money(d.ptkp)],['Saldo PPh nonfinal',d.balance===null?'Perlu verifikasi':d.balance>0?'Kurang bayar '+money(d.balance):d.balance<0?'Lebih bayar '+money(-d.balance):'Nihil']])}<div class="taxv-panel">${title('Metode hitung Orang Pribadi')}<div class="tax603-grid">${sel603('Metode nonfinal','tax603Method',{bookkeeping:'Pembukuan',nppn:'NPPN (bersyarat)'},p.method||'bookkeeping','onchange="taxV603MethodChange()"')}${field603('Persentase norma DJP (%)','tax603Norm',p.nppnRate||'','type="text" data-tax-decimal="1" inputmode="decimal" placeholder="Sesuai KLU dan wilayah"')}<label class="taxv-field full"><span><input type="checkbox" id="tax603Notified" ${p.nppnNotified?'checked':''}> Sudah menyampaikan pemberitahuan NPPN sesuai batas resmi</span></label></div><div class="taxv-actions"><button class="taxv-btn" onclick="taxV603SaveMethod()">Simpan Metode</button></div><p class="tax603-muted">Tarif progresif dan PTKP tidak dapat diubah bebas. Persentase NPPN wajib berasal dari tabel norma resmi berdasarkan KLU dan wilayah.</p></div>${d.warning?`<div class="tax603-tip warn">${htmlEscape(d.warning)}</div>`:''}
<div class="taxv-panel">${title('Rincian perhitungan')}<div class="taxv-row"><span>Penghasilan neto gaji / bukti potong</span><b>${money(d.salaryNet)}</b></div><div class="taxv-row"><span>Penghasilan nonfinal lain</span><b>${money(d.otherNet)}</b></div><div class="taxv-row"><span>Usaha/jasa nonfinal bruto</span><b>${money(d.businessGross)}</b></div><div class="taxv-row"><span>Omzet POS nonfinal terhubung</span><b>${money(d.posNormalGross)}</b></div><div class="taxv-row"><span>HPP POS (berdasarkan transaksi)</span><b>${money(d.posHpp)}</b></div><div class="taxv-row"><span>${d.method==='nppn'?'Neto NPPN':'Biaya fiskal manual'}</span><b>${money(d.method==='nppn'?d.bn:d.deductions)}</b></div><div class="taxv-row"><span>Jumlah neto nonfinal</span><b>${money(d.net)}</b></div><div class="taxv-row"><span>PTKP / PKP</span><b>${money(d.ptkp)} / ${money(d.pkp)}</b></div>${d.pr.items.map(e=>`<div class="taxv-row"><span>${money(e.base)} × ${e.rate*100}%</span><b>${money(e.tax)}</b></div>`).join('')}<div class="taxv-row"><span>Kredit pajak + PPh 25 tercatat</span><b>${money(d.credits)}</b></div><details class="taxv-info"><summary>Dasar hukum & pengecualian</summary><div>Tarif PPh Orang Pribadi berlapis 5%, 15%, 25%, 30%, 35% sesuai Pasal 17. PPh Final UMKM tidak menjadi kredit PPh progresif. Metode NPPN perlu kriteria, pemberitahuan, dan persentase KLU/wilayah. Tarif dan kelayakan final UMKM mengikuti PP 55/2022 pada 2025 dan PP 20/2026 berlaku mulai 22 April 2026, dengan ketentuan peralihan. Periksa kelayakan berdasarkan periode dan omzet keluarga. Penghasilan pasangan, luar negeri, biaya tertentu, serta NPPN membutuhkan pemeriksaan manusia.</div></details></div>${!isOP?'<div class="tax603-tip warn">Profil WP Badan: kalkulator PPh OP progresif tidak digunakan. Gunakan pencatatan pajak badan dan lakukan penghitungan sesuai aturan badan.</div>':''}<div class="taxv-panel">${title('PPh Final UMKM per masa')}${gridRows(a.rows,true)}<div class="taxv-actions"><button class="tax603-nav" onclick="taxV597Tab('pph')">Koreksi omzet / detail PPh UMKM ›</button></div></div>`}
window.taxV603MethodChange=function(){};
window.taxV603SaveMethod=function(){const method=val603('tax603Method'),rateRaw=val603('tax603Norm'),rate=rateRaw===''?null:taxV604ParseMoney(rateRaw);if(!['bookkeeping','nppn'].includes(method)||rate!==null&&(!Number.isFinite(rate)||rate<0||rate>100))return toast('Isi norma yang valid.','error');mutate603('Metode pajak disimpan.',c=>Object.assign(c.profileV603,{method,nppnRate:rate,nppnNotified:!!document.getElementById('tax603Notified')?.checked}))};
function monthlyStatus603(tax,month){if(tax===null)return 'Belum Dihitung';if(tax<=0)return 'Tidak Ada Kewajiban';const paid=data603().paymentRecordsV603.filter(e=>e.year===activeYear&&e.month===String(month).padStart(2,'0')&&e.kind==='umkm'&&e.ntpn&&e.paidDate).reduce((sum,e)=>sum+(Number(e.amount)||0),0);return paid>=tax?'Sudah Dibayar*':'Belum Dibayar';}
function renderMonthlyV603(a){const c=data603();return `<div class="taxv-filter">${yearSelector()}</div>${metrics([['Omzet pajak tahun ini',money(a.total)],['PPh Final 0,5% (estimasi)',a.tax===null?'Belum dihitung':money(a.tax)]])}<div class="taxv-panel">${title('Status 12 masa pajak')}<div class="tax603-cards">${a.rows.map(r=>`<div class="tax603-card"><div><b>${r.label} • ${money(r.turnover)}</b><small>PPh UMKM: ${r.tax===null?'—':money(r.tax)} • PPN POS ${money(r.vat)}</small></div><span class="taxv-status">${monthlyStatus603(r.tax,r.month)}</span></div>`).join('')}</div></div><div class="taxv-panel">${title('Kewajiban terkait')}<div class="tax603-row"><span class="tax603-muted">PPh 25, PPh 21/23/26, PPh final lain, dan PPN dicatat sesuai kewajiban Anda.</span><button class="tax603-nav" onclick="taxV597Tab('obligations')">PPh Lain ›</button></div><div class="taxv-actions"><button class="tax603-nav" onclick="taxV597Tab('payment')">Bayar / arsip bukti ›</button></div></div><p class="tax603-muted">*Sudah Dibayar = NTPN, tanggal, dan jumlah pembayaran yang diinput pengguna mencukupi estimasi. Belum diverifikasi langsung oleh DJP.</p>`}
function renderSettingsV603(){const c=data603(),p=c.preferencesV603;return renderProfile()+`<div class="taxv-panel">${title('Preferensi & integrasi')}<div class="tax603-grid">${sel603('Tahun fiskal awal','tax603Period',{calendar:'Januari–Desember (default)',custom:'Tahun buku berbeda • perlu verifikasi'},p.period||'calendar')}${sel603('Sumber akun','tax603Account',{pos:'Penjualan / kas INPOS',manual:'Catatan manual + POS'},p.account||'pos')}${sel603('Pengingat','tax603Notice',{on:'Aktif • ringkasan internal',off:'Nonaktif'},p.notice||'on')}${sel603('Format dokumen','tax603Document',{csv:'CSV / Excel',print:'Cetak / Simpan PDF'},p.document||'csv')}</div><div class="taxv-actions"><button class="taxv-btn" onclick="taxV603SavePreferences()">Simpan Preferensi</button></div><p class="tax603-muted">Izin akses mengikuti Pengaturan Karyawan INPOS. Tahun buku tidak standar dan aturan khusus perlu diperiksa sebelum pelaporan.</p></div>`}
