function renderReportV603(a){const cfg=data603(),p=cfg.profileV603,d=calculation603(a),assets=archive603('asset'),debts=archive603('debt'),family=archive603('dependent'),annualEntry=cfg.annualRecords[activeYear]||{},grossIncome=listTaxLedger603('income').reduce((t,e)=>t+e.amount,0),incomplete=[];if(!p.name)incomplete.push('Nama WP');if(!p.npwp)incomplete.push('NPWP/NIK');if(!p.address)incomplete.push('Alamat');if(cfg.type==='op'&&p.spouse==='separate')incomplete.push('Rekonsiliasi pajak suami–istri');if(p.method==='nppn'&&!d.nppnReady)incomplete.push('Validasi NPPN');if(!assets.length&&!p.nilAssets)incomplete.push('Daftar harta (atau konfirmasi nihil)');if(!debts.length&&!p.nilDebts)incomplete.push('Daftar utang (atau konfirmasi nihil)');if(!family.length&&Number(p.dependents)>0)incomplete.push('Daftar tanggungan keluarga');
return `<div class="taxv-filter">${yearSelector()}</div>${metrics([['Penghasilan POS + manual',money(a.total+grossIncome-a.rows.reduce((t,r)=>t+(r.manualBusiness||0),0))],['PPh OP progresif',d.due===null?'Perlu hitung':money(d.due)],['Kredit PPh nonfinal tercatat',money(d.credits)],['SPT Tahunan',annualEntry.status==='filed'?'Dilapor*':'Draf']])}<div class="taxv-panel">${title('Validasi SPT Tahunan')}<div class="tax603-tip ${incomplete.length?'warn':''}">${incomplete.length?'Perlu diperiksa: '+incomplete.map(htmlEscape).join(' • '):'Data pokok terisi. Tetap cocokkan dengan seluruh bukti resmi sebelum melapor.'}</div><div class="tax603-kv" style="margin-top:8px"><div><small>Harta dicatat</small><b>${assets.length} item</b></div><div><small>Utang dicatat</small><b>${debts.length} item</b></div><div><small>Tanggungan dicatat</small><b>${family.length} orang</b></div><div><small>Perkiraan kurang/lebih bayar</small><b>${d.balance===null?'—':money(d.balance)}</b></div></div></div>
<details class="taxv-info"><summary>Rincian penghasilan final, nonfinal, dan bukan objek</summary><div>${[['PPh Final UMKM',a.total],['Final lain',listTaxLedger603('income').filter(e=>e.taxClass==='final').reduce((t,e)=>t+e.amount,0)],['Nonfinal manual',listTaxLedger603('income').filter(e=>e.taxClass==='normal').reduce((t,e)=>t+e.amount,0)],['Bukan objek',listTaxLedger603('income').filter(e=>e.taxClass==='exempt').reduce((t,e)=>t+e.amount,0)]].map(([name,n])=>`<div class="taxv-row"><span>${name}</span><b>${money(n)}</b></div>`).join('')}Catatan: rekap final UMKM mencakup omzet terhubung, koreksi, dan manual usaha yang diklasifikasi UMKM.</div></details><div class="taxv-panel">${title('Harta, utang, keluarga')}<div class="tax603-grid">${sel603('Kelompok','tax603AssetType',{asset:'Harta',debt:'Utang',dependent:'Tanggungan keluarga'},'asset')}${field603('Nama / uraian','tax603AssetName','','maxlength="120" placeholder="Nama harta / utang / keluarga"')}${field603('Nilai akhir tahun (Rp)','tax603AssetAmount','','type="text" data-tax-decimal="1" inputmode="decimal" placeholder="0 untuk tanggungan"')}${field603('Catatan / referensi','tax603AssetNote','','maxlength="100"')}
</div><div class="taxv-actions"><button class="taxv-btn" onclick="taxV603AddAsset()">Tambah Data</button>${!assets.length?`<button class="taxv-btn secondary" onclick="taxV603Nil('asset')">${p.nilAssets?'Harta nihil ✓':'Konfirmasi harta nihil'}</button>`:''}${!debts.length?`<button class="taxv-btn secondary" onclick="taxV603Nil('debt')">${p.nilDebts?'Utang nihil ✓':'Konfirmasi utang nihil'}</button>`:''}</div><div class="tax603-cards" style="margin-top:8px">${['asset','debt','dependent'].flatMap(type=>archive603(type).map(e=>`<div class="tax603-card"><div><b>${htmlEscape(({asset:'Harta',debt:'Utang',dependent:'Keluarga'})[type])}: ${htmlEscape(e.name)} ${type==='dependent'?'':'• '+money(e.amount)}</b><small>${htmlEscape(e.note||'')} • Tahun ${activeYear}</small></div><button class="taxv-btn secondary" onclick="taxV603DeleteAsset('${htmlEscape(e.id)}')">Hapus</button></div>`)).join('')||'<p class="taxv-muted">Belum ada daftar harta, utang, atau keluarga.</p>'}</div></div>
<div class="taxv-panel">${title('Pelaporan & Bukti Penerimaan Elektronik')}<div class="tax603-grid">${sel603('Status pelaporan','tax603SPTStatus',{draft:'Draf • belum dilapor',filed:'Sudah dilapor (input BPE)'},annualEntry.status||'draft')}${field603('Nomor BPE resmi','tax603SPTBPE',annualEntry.reference||'','maxlength="90" placeholder="Dari Coretax DJP"')}${field603('Tanggal lapor','tax603SPTDate',annualEntry.date||'','type="date"')}${sel603('Jenis dokumen','tax603SPTKind',{normal:'SPT Tahunan',amended:'SPT Pembetulan'},annualEntry.kind||'normal')}<label class="taxv-field tax603-span"><span>Lampiran BPE (opsional • maksimal 120 KB)</span><input id="tax603SPTFile" type="file" accept="application/pdf,image/jpeg,image/png"></label></div><div class="taxv-actions"><button class="taxv-btn" onclick="taxV603SaveSPT()">Simpan Arsip SPT</button>${annualEntry.file?.name?`<button class="taxv-btn secondary" onclick="taxV603OpenAttachment('annual','spt')">Buka BPE</button>`:''}<button class="taxv-btn secondary" onclick="taxV603PrintSummary()">Pratinjau / PDF</button><button class="taxv-btn secondary" onclick="taxV603DownloadCSV()">Ekspor Excel (CSV)</button></div><p class="tax603-muted">Status dan BPE dicatat manual, bukan verifikasi DJP. Dokumen ini bukan formulir impor Coretax.</p></div><details class="taxv-info"><summary>Ringkasan cara lapor</summary><div>Periksa bukti potong gaji, daftar usaha dan pekerjaan bebas, PPh Final, penghasilan bukan objek, utang/piutang, harta, dan perhitungan kredit. Masuk secara mandiri ke <a href="https://coretaxdjp.pajak.go.id/" target="_blank" rel="noopener noreferrer">Coretax DJP ↗</a>, lakukan verifikasi dan kirim SPT melalui saluran resmi, lalu arsipkan BPE di INPOS.</div></details>`}
window.taxV603AddAsset=function(){const type=val603('tax603AssetType'),name=val603('tax603AssetName'),amount=num603('tax603AssetAmount'),note=val603('tax603AssetNote');if(!['asset','debt','dependent'].includes(type)||!name||!validMoney603(amount))return toast('Lengkapi nama dan nominal yang valid.','error');mutate603('Data pendukung SPT disimpan.',c=>{c.archiveItemsV603.unshift({id:'as-'+Date.now()+'-'+Math.random().toString(36).slice(2),year:activeYear,type,name,amount,note})})};
window.taxV603Nil=function(type){if(!['asset','debt'].includes(type))return;mutate603('Konfirmasi data nihil diperbarui.',c=>{const key=type==='asset'?'nilAssets':'nilDebts';c.profileV603[key]=!c.profileV603[key]})};
window.taxV603DeleteAsset=function(id){if(!confirm('Hapus item pendukung SPT ini?'))return;mutate603('Data pendukung SPT dihapus.',c=>{c.archiveItemsV603=c.archiveItemsV603.filter(e=>e.id!==id)})};
window.taxV603SaveSPT=async function(){const status=val603('tax603SPTStatus'),reference=val603('tax603SPTBPE'),date=val603('tax603SPTDate'),kind=val603('tax603SPTKind');if(status==='filed'&&(!reference||!date))return toast('Status Sudah Dilapor wajib nomor BPE dan tanggal lapor.','error');if(!taxV597ValidDate(date))return toast('Tanggal tidak valid.','error');let file=null;try{file=await file603(document.getElementById('tax603SPTFile'))}catch(e){return toast(e.message,'error')}mutate603('SPT Tahunan dicatat manual.',c=>{c.annualRecords[activeYear]={status,reference,date,kind,file:file||c.annualRecords[activeYear]?.file||null}})};
function dueByKey603(kind,month,a){if(kind==='umkm')return a.rows[Number(month)-1]?.tax??null;const ob=data603().obligations[`${activeYear}-${month}:${kind}`];if(ob)return Number(ob.amount)||0;return null}
